var t=`0499-galayet-bandora`;var i=`world-0499`;var a=`JO`;var o=`western-asia`;var r=4;var s=33;var l={en:`Galayet Bandora`,ua:`Галаєт бандора`};var g={en:`A traditional dish from Jordan, centered on yellow onion, garlic, tomato, green bell pepper. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Йорданія. Основні складники: жовта цибуля, часник, помідор, зелений солодкий перець. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,180,`g`],[`extra-virgin-olive-oil`,50,`ml`],[`garlic`,4,`clove`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 20 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 20 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:20,i:[[`tomato`,800,`g`],[`green-bell-pepper`,220,`g`],[`hot-paprika`,3,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,30,`g`],[`table-salt`,null,`to_taste`]]}];var m={slug:t,id:i,country:`JO`,region:o,servings:4,minutes:33,title:l,text:g,steps:d};export{a as country,m as default,i as id,s as minutes,o as region,r as servings,t as slug,d as steps,g as text,l as title};